corrected_code:
package campaign

import (
	"context"
	"errors"
	"myapp/crm"
	"myapp/sms"
)

type DispatchPayload struct {
	CampaignID string
	UserID     string
}

type CampaignWorker struct {
	CRM crm.Store
	SMS sms.Sender
}

func (w *CampaignWorker) HandleDispatch(ctx context.Context, payload DispatchPayload) error {
	camp, err := w.CRM.LoadCampaign(ctx, payload.CampaignID)
	if err != nil {
		return err
	}

	if camp.OwnerUserID != payload.UserID {
		return errors.New("dispatch worker: user is not the owner of this campaign")
	}

	return w.SMS.Broadcast(ctx, camp.Recipients, camp.MessageBody)
}
